package dev.myjarvis.core;

import java.nio.charset.StandardCharsets;
import java.util.*;
import org.junit.jupiter.api.Test;
import tools.jackson.databind.JsonNode;
import tools.jackson.databind.node.ObjectNode;
import static org.junit.jupiter.api.Assertions.*;

class StudyFeedbackResultTest {
    static ObjectNode request(){
        ObjectNode request=(ObjectNode)LocalInferenceContractTest.request();request.remove("user_input");request.put("purpose","STUDY_FEEDBACK");
        ((ObjectNode)request.get("budget")).put("max_compute_ms",60000).put("max_input_tokens",3584).put("max_model_calls",1);
        request.put("prompt_revision","local-v1");request.set("context",Json.MAPPER.valueToTree(Map.of("id",UUID.randomUUID(),"revision",1)));
        request.set("control",Json.MAPPER.valueToTree(Map.of("revision",1,"origin_binding","b".repeat(64),"dispatch_commitment","c".repeat(64),"security_epoch",1)));
        for(String field:List.of("history","memories","evidence","tool_results","allowed_tool_ids"))request.set(field,Json.MAPPER.valueToTree(List.of()));
        var source=new LinkedHashMap<String,Object>();source.put("revision",1);source.put("study_version",3);source.put("lesson_run_version",2);
        for(String field:List.of("feedback_id","study_session_id","lesson_run_id","question_id","input_id","attempt_id"))source.put(field,UUID.randomUUID());
        source.put("lesson",Map.of("concepts",List.of("One","Two","Three"),"questions",List.of(Map.of("id",source.get("question_id"),"text","Which synthetic boundary?"),Map.of("id",UUID.randomUUID(),"text","What changes?"))));
        source.put("answer",Map.of("source_kind","OWNER_STUDY_ANSWER_INPUT","role","USER","trust","USER_DIRECT","text","A stored synthetic answer"));request.set("feedback_source",Json.MAPPER.valueToTree(source));return request;
    }
    static ObjectNode response(JsonNode request){return (ObjectNode)Json.MAPPER.valueToTree(Map.of("kind","FEEDBACK","assessment","PARTIALLY_CORRECT","explanation","The boundary condition needs another check.","example","if (size == 0) return;","assumptions",List.of("The input size is nonnegative."),"review_checklist",List.of("Check the empty case."),"usage",LocalInferenceContractTest.response(request).get("usage")));}
    static Map<String,Object> target(JsonNode request){var target=new LinkedHashMap<String,Object>();for(String field:List.of("feedback_id","study_session_id","lesson_run_id","question_id","input_id","attempt_id"))target.put(field,request.get("feedback_source").get(field));return target;}
    @Test void closedFeedbackRoundTripsOneCanonicalInertResult(){var request=request();var response=response(request);assertNull(LocalInferenceService.validate(response,request));String stored=StudyFeedbackResult.encodeAccepted(target(request),response);var view=StudyFeedbackResult.projectStored(target(request),stored);assertEquals("NOT_RUN",view.get("code_execution"));assertEquals(1,view.get("revision"));assertFalse(stored.contains("usage"));assertFalse(stored.contains("mastery"));}
    @Test void everyGeneratedAuthorityAndUnknownFieldIsRejected(){for(String field:List.of("owner_id","feedback_id","score","mastery","verified","completed","tool","citation","code_execution")){var request=request();var response=response(request);response.put(field,"untrusted");assertThrows(ApiException.class,()->StudyFeedbackResult.validateWire(response,request));}}
    @Test void feedbackCannotSubstituteOrdinaryLessonOrClarificationKinds(){var request=request();for(String kind:List.of("ANSWER","LESSON","NEED_INPUT","TOOL_PROPOSALS")){var response=response(request);response.put("kind",kind);assertThrows(ApiException.class,()->LocalInferenceService.validate(response,request));}}
    @Test void requiredTextListsAndUnicodeLimitsAreStrict(){for(String value:List.of(""," ","\u0085","\u0000","text\u0000","x".repeat(2001))){var request=request();var response=response(request);response.put("explanation",value);assertThrows(ApiException.class,()->StudyFeedbackResult.validateWire(response,request));}var request=request();var response=response(request);response.put("example","😀".repeat(2000));assertDoesNotThrow(()->StudyFeedbackResult.validateWire(response,request));for(Object values:List.of(List.of(),List.of("a","b","c","d"),List.of(" "),List.of("x".repeat(501)))){response.set("assumptions",Json.MAPPER.valueToTree(values));assertThrows(ApiException.class,()->StudyFeedbackResult.validateWire(response,request));}}
    @Test void usageIdentityAndActualBudgetsCannotBeForged(){for(String field:List.of("inference_request_id","reservation_id","model_manifest_hash")){var request=request();var response=response(request);((ObjectNode)response.get("usage")).put(field,field.equals("model_manifest_hash")?"f".repeat(64):UUID.randomUUID().toString());assertThrows(ApiException.class,()->StudyFeedbackResult.validateWire(response,request));}for(String field:List.of("input_tokens","output_tokens","compute_ms")){var request=request();var response=response(request);((ObjectNode)response.get("usage")).put(field,60001);assertThrows(ApiException.class,()->StudyFeedbackResult.validateWire(response,request));}}
    @Test void missingControlGenericMessagesAndNonemptyContextFailClosed(){for(String field:List.of("control","context","feedback_source")){var request=request();request.remove(field);assertThrows(ApiException.class,()->LocalInferenceService.validate(response(request),request));}var request=request();request.put("user_input","fabricated");assertThrows(ApiException.class,()->StudyFeedbackResult.validateWire(response(request),request));request.remove("user_input");request.set("memories",Json.MAPPER.valueToTree(List.of("injected")));assertThrows(ApiException.class,()->StudyFeedbackResult.validateWire(response(request),request));}
    @Test void storedTargetCanonicalityAndExecutionClaimsAreVerified(){var request=request();String stored=StudyFeedbackResult.encodeAccepted(target(request),response(request));var wrong=new LinkedHashMap<>(target(request));wrong.put("input_id",UUID.randomUUID());assertThrows(ApiException.class,()->StudyFeedbackResult.projectStored(wrong,stored));assertThrows(ApiException.class,()->StudyFeedbackResult.projectStored(target(request)," "+stored));assertThrows(ApiException.class,()->StudyFeedbackResult.projectStored(target(request),stored.replace("NOT_RUN","VERIFIED")));}
    @Test void duplicateKeysInvalidUtf8AndSurrogatesNeverBecomeModelData(){assertThrows(ApiException.class,()->Json.parse("{\"kind\":\"FEEDBACK\",\"kind\":\"ERROR\"}".getBytes(StandardCharsets.UTF_8)));assertThrows(ApiException.class,()->Json.parse(new byte[]{(byte)0xc3,0x28}));var request=request();var response=response(request);response.put("example","\uD800");assertThrows(ApiException.class,()->StudyFeedbackResult.validateWire(response,request));}
}
